export declare const cssText = "\n.dsh_lanproxy_section {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  min-width: 0;\n}\n.dsh_lanproxy_heading {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n.dsh_lanproxy_title {\n  margin: 0;\n  color: var(--dsw-alias-label-primary, #e6edf3);\n  font-size: 18px;\n  line-height: 26px;\n  font-weight: 600;\n}\n.dsh_lanproxy_subtitle {\n  margin: 0;\n  color: var(--dsw-alias-label-tertiary, #8b949e);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_lanproxy_card {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  min-width: 0;\n  padding: 14px 16px;\n  border: 1px solid var(--dsw-alias-border-l2, #30363d);\n  border-radius: 12px;\n  background: var(--dsw-alias-bg-layer-1, #161b22);\n}\n.dsh_lanproxy_cardTitle {\n  color: var(--dsw-alias-label-primary, #e6edf3);\n  font-size: 14px;\n  line-height: 20px;\n  font-weight: 600;\n}\n.dsh_lanproxy_cardHeader {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-width: 0;\n}\n.dsh_lanproxy_controls {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.dsh_lanproxy_cardDesc {\n  margin: -4px 0 0;\n  color: var(--dsw-alias-label-tertiary, #8b949e);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_lanproxy_row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-width: 0;\n}\n.dsh_lanproxy_rowLabel {\n  color: var(--dsw-alias-label-secondary, #c9d1d9);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_lanproxy_rowValue {\n  color: var(--dsw-alias-label-primary, #e6edf3);\n  font-size: 13px;\n  line-height: 20px;\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n.dsh_lanproxy_portStatus {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n.dsh_lanproxy_dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  flex: none;\n}\n.dsh_lanproxy_dotOn {\n  background: var(--dsw-alias-fg-positive, #3fb950);\n  box-shadow: 0 0 0 3px var(--dsw-alias-bg-positive, rgba(35, 134, 54, 0.25));\n}\n.dsh_lanproxy_dotOff {\n  background: var(--dsw-alias-fg-danger, #f85149);\n  box-shadow: 0 0 0 3px var(--dsw-alias-bg-danger, rgba(248, 81, 73, 0.15));\n}\n.dsh_lanproxy_portValue {\n  color: var(--dsw-alias-label-primary, #e6edf3);\n  font-variant-numeric: tabular-nums;\n}\n.dsh_lanproxy_statusText {\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_lanproxy_statusTextOn {\n  color: var(--dsw-alias-fg-positive, #3fb950);\n}\n.dsh_lanproxy_statusTextOff {\n  color: var(--dsw-alias-fg-danger, #f85149);\n}\n.dsh_lanproxy_badge {\n  padding: 2px 8px;\n  border-radius: 999px;\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_lanproxy_badgeOn {\n  color: var(--dsw-alias-fg-positive, #3fb950);\n  background: var(--dsw-alias-bg-positive, rgba(35, 134, 54, 0.25));\n}\n.dsh_lanproxy_badgeOff {\n  color: var(--dsw-alias-fg-danger, #f85149);\n  background: var(--dsw-alias-bg-danger, rgba(248, 81, 73, 0.15));\n}\n.dsh_lanproxy_form {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  min-width: 0;\n}\n.dsh_lanproxy_field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n}\n.dsh_lanproxy_fieldLabel {\n  color: var(--dsw-alias-label-secondary, #c9d1d9);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_lanproxy_fieldHint {\n  color: var(--dsw-alias-label-tertiary, #8b949e);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_lanproxy_input {\n  width: 100%;\n  padding: 8px 10px;\n  border: 1px solid var(--dsw-alias-border-l2, #30363d);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-0, #0d1117);\n  color: var(--dsw-alias-label-primary, #e6edf3);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_lanproxy_input:focus {\n  outline: none;\n  border-color: var(--dsw-alias-accent, #2f81f7);\n}\n.dsh_lanproxy_passwordWrap {\n  position: relative;\n  display: flex;\n  align-items: center;\n  min-width: 0;\n}\n.dsh_lanproxy_passwordInput {\n  padding-right: 36px;\n}\n.dsh_lanproxy_eye {\n  position: absolute;\n  right: 6px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--dsw-alias-label-tertiary, #8b949e);\n  cursor: pointer;\n}\n.dsh_lanproxy_eye:hover {\n  color: var(--dsw-alias-label-primary, #e6edf3);\n  background: var(--dsw-alias-bg-layer-2, #21262d);\n}\n.dsh_lanproxy_eye svg {\n  width: 16px;\n  height: 16px;\n}\n.dsh_lanproxy_statusError {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 8px;\n  min-width: 0;\n}\n.dsh_lanproxy_actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin-top: 2px;\n}\n/* Primary button (\u542F\u52A8 / \u5E94\u7528): filled accent with a visible border. */\n.dsh_lanproxy_button {\n  padding: 7px 14px;\n  border: 1px solid var(--dsw-alias-accent, #2f81f7);\n  border-radius: 8px;\n  background: var(--dsw-alias-accent, #2f81f7);\n  color: var(--dsw-alias-fg-on-accent, #ffffff);\n  font-size: 13px;\n  line-height: 20px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n.dsh_lanproxy_button:hover:not(:disabled) {\n  background: var(--dsw-alias-accent-hover, #388bfd);\n  border-color: var(--dsw-alias-accent-hover, #388bfd);\n}\n.dsh_lanproxy_button:active:not(:disabled) {\n  background: var(--dsw-alias-accent-active, #1f6feb);\n  border-color: var(--dsw-alias-accent-active, #1f6feb);\n}\n.dsh_lanproxy_button:disabled {\n  opacity: 0.5;\n  cursor: default;\n  border-color: var(--dsw-alias-border-l2, #30363d);\n  background: var(--dsw-alias-bg-layer-2, #21262d);\n  color: var(--dsw-alias-label-tertiary, #8b949e);\n}\n/* Secondary button (\u505C\u6B62): outline style with its own border. */\n.dsh_lanproxy_buttonStop {\n  background: var(--dsw-alias-bg-layer-1, #161b22);\n  border: 1px solid var(--dsw-alias-border-l2, #30363d);\n  color: var(--dsw-alias-label-primary, #e6edf3);\n}\n.dsh_lanproxy_buttonStop:hover:not(:disabled) {\n  background: var(--dsw-alias-bg-layer-2, #21262d);\n  border-color: var(--dsw-alias-label-tertiary, #8b949e);\n}\n.dsh_lanproxy_buttonStop:active:not(:disabled) {\n  background: var(--dsw-alias-bg-layer-0, #0d1117);\n}\n.dsh_lanproxy_buttonStop:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n.dsh_lanproxy_message {\n  margin: 0;\n  color: var(--dsw-alias-fg-positive, #3fb950);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_lanproxy_error {\n  margin: 0;\n  color: var(--dsw-alias-fg-danger, #f85149);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_lanproxy_hint {\n  margin: 0;\n  color: var(--dsw-alias-label-tertiary, #8b949e);\n  font-size: 12px;\n  line-height: 18px;\n}\n";
